// ===== ASP.NET Core 控制器（对标 Spring Boot @RestController） =====
using Microsoft.AspNetCore.Mvc;

[ApiController]
[Route("api/[controller]")]
public class UsersController : ControllerBase
{
    // DI 注入（对标 @Autowired，注意：.NET 默认 Transient，Spring 默认 Singleton）
    private readonly IUserService _service;
    private readonly ILogger<UsersController> _logger;

    public UsersController(IUserService service, ILogger<UsersController> logger)
    {
        _service = service;  // 构造函数注入，非 @Autowired 字段注入
        _logger = logger;
    }

    // GET /api/users/5
    [HttpGet("{id}")]
    public async Task<ActionResult<User>> GetUser(int id)  // async/await 对标 CompletableFuture
    {
        var user = await _service.GetByIdAsync(id);  // await 自动解包 Task，对标 .get()
        if (user == null) return NotFound();
        return Ok(user);
    }
}

// ===== DI 注册（对标 Spring @Configuration @Bean） =====
// Program.cs
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddScoped<IUserService, UserService>();  // Scoped = 每个HTTP请求一个实例
builder.Services.AddSingleton<ICacheService, RedisCacheService>();  // Singleton = 全局单例
// Spring 等价：@Service（默认singleton） / @Scope("request")

// ===== EF Core 查询（对标 Hibernate JPQL 或 Stream API） =====
public class UserRepository
{
    private readonly AppDbContext _db;

    public async Task<List<User>> GetActiveAdultsAsync()
    {
        // LINQ 查询语法（对标 JPQL：SELECT u FROM User u WHERE u.IsActive = true AND u.Age >= 18）
        return await _db.Users
            .Where(u => u.IsActive && u.Age >= 18)  // 编译期类型检查，JPQL是字符串
            .OrderBy(u => u.Name)
            .AsNoTracking()  // 只读查询禁用变更追踪，提升性能
            .ToListAsync();
    }
}

